import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build graph: employee -> set of languages
    lang_know = []
    for _ in range(n):
        k = int(next(it))
        langs = set()
        for _ in range(k):
            langs.add(int(next(it)))
        lang_know.append(langs)

    # Build adjacency list: employee -> list of connected employees
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if lang_know[i] & lang_know[j]:
                adj[i].append(j)
                adj[j].append(i)

    # Find connected components using BFS
    visited = [False] * n
    components = 0

    for i in range(n):
        if not visited[i]:
            components += 1
            queue = deque([i])
            visited[i] = True

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)

    print(components - 1)

if __name__ == "__main__":
    solve()
"}

