import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    d = int(data[idx]); idx += 1
    n = int(data[idx]); m = int(data[idx+1]); idx += 2

    sofas = []
    for i in range(d):
        x1 = int(data[idx]); y1 = int(data[idx+1])
        x2 = int(data[idx+2]); y2 = int(data[idx+3])
        idx += 4

        min_x = min(x1, x2)
        max_x = max(x1, x2)
        min_y = min(y1, y2)
        max_y = max(y1, y2)

        sofas.append((min_x, max_x, min_y, max_y))

    cntl = int(data[idx]); cntr = int(data[idx+1]); cntt = int(data[idx+2]); cntb = int(data[idx+3]);

    for i in range(d):
        min_x_i, max_x_i, min_y_i, max_y_i = sofas[i]

        # Count sofas to the left
        left_count = 0
        for j in range(d):
            if i == j:
                continue
            min_x_j, max_x_j, min_y_j, max_y_j = sofas[j]

            # Sofa j is to the left of sofa i if there exists a cell in j with x < a cell in i
            if (min_x_j < max_x_i) or (max_x_j < max_x_i) or (min_x_j < min_x_i) or (max_x_j < min_x_i):
                left_count += 1

        # Count sofas to the right
        right_count = 0
        for j in range(d):
            if i == j:
                continue
            min_x_j, max_x_j, min_y_j, max_y_j = sofas[j]

            # Sofa j is to the right of sofa i if there exists a cell in j with x > a cell in i
            if (min_x_j > min_x_i) or (max_x_j > max_x_i) or (min_x_j > min_x_i) or (max_x_j > max_x_i):
                right_count += 1

        # Count sofas to the top
        top_count = 0
        for j in range(d):
            if i == j:
                continue
            min_x_j, max_x_j, min_y_j, max_y_j = sofas[j]

            # Sofa j is to the top of sofa i if there exists a cell in j with y < a cell in i
            if (min_y_j < max_y_i) or (max_y_j < max_y_i) or (min_y_j < min_y_i) or (max_y_j < min_y_i):
                top_count += 1

        # Count sofas to the bottom
        bottom_count = 0
        for j in range(d):
            if i == j:
                continue
            min_x_j, max_x_j, min_y_j, max_y_j = sofas[j]

            # Sofa j is to the bottom of sofa i if there exists a cell in j with y > a cell in i
            if (min_y_j > min_y_i) or (max_y_j > max_y_i) or (min_y_j > min_y_i) or (max_y_j > max_y_i):
                bottom_count += 1

        if left_count == cntl and right_count == cntr and top_count == cntt and bottom_count == cntb:
            print(i + 1)
            return

    print(-1)

if __name__ == "__main__":
    solve()
