def F(t, A, B, C, D):
    return A * t * t * t + B * t * t + C * t + D

def find_max_t(A, B, C, D, K):
    # Binary search bounds
    low = 0
    high = 10**18  # Since F(t) ≤ 10^18

    # Find the smallest t where F(t) > K
    while low < high:
        mid = (low + high) // 2
        if F(mid, A, B, C, D) > K:
            high = mid
        else:
            low = mid + 1

    # The answer is low - 1
    return low - 1

T = int(input())
for _ in range(T):
    A, B, C, D, K = map(int, input().split())
    print(find_max_t(A, B, C, D, K))
