def is_even_permutation(arr):
    """Check if the permutation needed to sort arr is even"""
    n = len(arr)
    # Count inversions
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                inversions += 1
    return inversions % 2 == 0

def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    t = int(input[0])
    idx = 1

    for _ in range(t):
        n = int(input[idx])
        idx += 1
        arr = list(map(int, input[idx:idx+n]))
        idx += n

        if n % 2 == 1:
            print("YES")
        else:
            if is_even_permutation(arr):
                print("YES")
            else:
                print("NO")

if __name__ == "__main__":
    solve()
