# Dictionary: time -> set of busy servers
busy_at_time = {}

for _ in range(q):
    ti, ki, di = map(int, input().split())

    # Find unoccupied servers at time ti
    busy = busy_at_time.get(ti, set())
    unoccupied = [s for s in range(1, n+1) if s not in busy]

    if len(unoccupied) >= ki:
        # Assign ki smallest unoccupied servers
        assigned = unoccupied[:ki]
        print(sum(assigned))

        # Mark these servers as busy from ti to ti + di - 1
        for s in assigned:
            for t in range(ti, ti + di):
                if t not in busy_at_time:
                    busy_at_time[t] = set()
                busy_at_time[t].add(s)
    else:
        print(-1)
