def count_digit(n, d):
    count = 0
    i = 1
    while i <= n:
        count += (n // (i * 10)) * i
        if d == 4:
            count += max(0, min(n % (i * 10) - 4 * i + 1, i))
        elif d == 7:
            count += max(0, min(n % (i * 10) - 7 * i + 1, i))
        i *= 10
    return count

def solve():
    T = int(input())
    for _ in range(T):
        N = int(input())

        # Compute prefix sums
        prefix4 = [0] * (N + 1)
        prefix7 = [0] * (N + 1)

        for i in range(1, N + 1):
            prefix4[i] = prefix4[i-1] + count_digit(i, 4)
            prefix7[i] = prefix7[i-1] + count_digit(i, 7)

        # Compute diff array
        diff = [prefix4[i] - prefix7[i] for i in range(N + 1)]

        # Count frequency of each diff value
        freq = {}
        for val in diff:
            freq[val] = freq.get(val, 0) + 1

        # Count valid pairs
        result = 0
        for count in freq.values():
            result += count * (count - 1) // 2

        print(result)

solve()
"}

