def count_less_equal(ranges, target):
    """Count how many distinct numbers are ≤ target"""
    count = 0
    for a, b in ranges:
        if b <= target:
            count += b - a + 1
        elif a <= target:
            count += target - a + 1
    return count

def find_kth_smallest(ranges, k):
    """Find the Kth smallest number in the sequence"""
    low = min(a for a, b in ranges)
    high = max(b for a, b in ranges)

    while low < high:
        mid = (low + high) // 2
        cnt = count_less_equal(ranges, mid)

        if cnt < k:
            low = mid + 1
        else:
            high = mid

    # After loop, low == high, check if it's actually present
    for a, b in ranges:
        if a <= low <= b:
            return low

    return -1

